using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseContent = response.Text ?? string.Empty;

        var evaluators = new IEvaluator[]
        {
            new RelevancyEvaluator(),
            new CoherenceEvaluator(),
        };

        var chatHistory = new List<ChatMessage>(messages)
        {
            new(ChatRole.Assistant, responseContent)
        };

        var evaluationResult = await EvaluatorExtensions.EvaluateAsync(
            evaluators,
            chatHistory,
            _evaluatorClient);

        foreach (var result in evaluationResult)
        {
            Assert.IsFalse(
                result.Value.Rating == EvaluationRating.Inconclusive,
                $"Evaluator '{result.Key}' returned inconclusive.");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsCoherent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in two sentences.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseContent = response.Text ?? string.Empty;

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
        };

        var chatHistory = new List<ChatMessage>(messages)
        {
            new(ChatRole.Assistant, responseContent)
        };

        var evaluationResult = await EvaluatorExtensions.EvaluateAsync(
            evaluators,
            chatHistory,
            _evaluatorClient);

        foreach (var result in evaluationResult)
        {
            Assert.IsFalse(
                result.Value.Rating == EvaluationRating.Inconclusive,
                $"Evaluator '{result.Key}' returned inconclusive.");
        }
    }
}

